{"cards": [{"node_code": "N_c96902e990a1bffb", "definition": "研究通过工艺优化、近净成形及结构设计协同，提升原材料在制造过程中的有效利用率，减少废料产生与材料消耗的技术。", "boundary": "聚焦于“材料”这一特定资源的投入效率，关注从毛坯到成品的材料去除率、利用率及轻量化设计对制造的影响。边界在于不涉及能源消耗（归入“机床、工艺与工厂能效”）或辅助介质（归入“水、辅助介质与公用工程优化”），也不涉及产品报废后的回收处理。", "includes": ["近净成形、增材制造等减材/无材工艺对材料利用率的提升", "基于拓扑优化或轻量化设计的材料减量化制造策略", "切削、冲压等工艺中的余量优化与废料最小化技术"], "excludes": ["机床主轴或驱动系统的电能效率优化", "冷却液、压缩空气等辅助介质的消耗控制"], "sibling_distinctions": [{"other_code": "N_7e08ab44f1aef45e", "rule": "本节点关注“材料”用量的节约（少用材料），兄弟节点关注“能源”消耗的降低（少用电/气）。"}, {"other_code": "N_2cfef0e8ffec48bb", "rule": "本节点关注固体原材料的利用效率，兄弟节点关注水、气等流体辅助介质的循环与节约。"}], "cross_boundary_rule": "若研究同时涉及材料利用率与能耗，需根据主要优化目标判定：若核心指标为材料去除率或废料比，主挂载本节点；若核心指标为比能耗，主挂载“机床、工艺与工厂能效”。"}, {"node_code": "N_7e08ab44f1aef45e", "definition": "研究机床、工艺装备及工厂层面的能源消耗监测、能效评估与节能优化技术，旨在降低制造过程的电力、热力等能源需求。", "boundary": "聚焦于“能源”输入端的效率，涵盖单机设备能效、工艺过程能耗模型及工厂整体能源管理系统。边界在于关注能量转换与使用的效率，不涉及材料本身的用量优化（归入“材料利用率与减量化”）或辅助介质的流体管理（归入“水、辅助介质与公用工程优化”）。", "includes": ["机床主轴、进给系统等关键部件的能效分析与优化", "基于工艺参数（如切削速度、进给量）的能耗建模与节能策略", "工厂级能源管理系统（EMS）及生产调度中的能耗优化"], "excludes": ["原材料的利用率提升或轻量化设计", "冷却水、压缩空气等辅助介质的泄漏检测与循环使用"], "sibling_distinctions": [{"other_code": "N_c96902e990a1bffb", "rule": "本节点关注“能源”消耗的降低（少用电/气），兄弟节点关注“材料”用量的节约（少用材料）。"}, {"other_code": "N_2cfef0e8ffec48bb", "rule": "本节点关注电能、热能等一次/二次能源的效率，兄弟节点关注水、压缩空气等辅助介质的资源效率。"}], "cross_boundary_rule": "若研究涉及通过降低材料去除率来间接降低能耗，主挂载“材料利用率与减量化”；若研究直接针对电机效率、传动效率或工艺能耗模型，主挂载本节点。"}, {"node_code": "N_2cfef0e8ffec48bb", "definition": "研究制造过程中冷却水、压缩空气、润滑液等辅助介质及公用工程系统的优化管理、循环利用与节约技术。", "boundary": "聚焦于“辅助介质”与“公用工程”的资源效率，关注流体介质的消耗、回收、净化及系统压力/流量优化。边界在于关注非主要能源（电/热）和非主要原材料（金属/塑料）的流体资源管理，不涉及电能效率（归入“机床、工艺与工厂能效”）或固体材料利用率（归入“材料利用率与减量化”）。", "includes": ["切削液、磨削液等工艺介质的过滤、再生与循环利用技术", "压缩空气系统的泄漏检测、压力优化与节能管理", "冷却水系统的闭路循环、水质控制及节水技术"], "excludes": ["机床主驱动系统的电能效率优化", "金属或塑料等固体原材料的利用率提升"], "sibling_distinctions": [{"other_code": "N_c96902e990a1bffb", "rule": "本节点关注流体辅助介质（水、气、液）的节约，兄弟节点关注固体原材料的利用效率。"}, {"other_code": "N_7e08ab44f1aef45e", "rule": "本节点关注辅助介质本身的资源效率（如节水、节气），兄弟节点关注驱动这些介质或设备的能源效率（如节电）。"}], "cross_boundary_rule": "若研究涉及压缩空气系统的电能效率，主挂载“机床、工艺与工厂能效”；若研究涉及压缩空气的泄漏减少或压力匹配优化，主挂载本节点。"}]}
